code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            r0 = min(y for y,x in comp); r1 = max(y for y,x in comp)
            c0 = min(x for y,x in comp); c1 = max(x for y,x in comp)
            top_gaps = [x for x in range(c0,c1+1) if grid[r0][x] != 5]
            if r1-r0 >= 2 and top_gaps:
                gap = top_gaps[0]
                for y in range(r0, r1+1):
                    for x in range(c0, c1+1):
                        if out[y][x] == 0:
                            out[y][x] = 2
                if r0 > 0:
                    if gap > (c0+c1)/2:
                        for x in range(gap+1): out[r0-1][x] = 2
                    else:
                        for x in range(gap,w): out[r0-1][x] = 2
    return out
'''
